// Random verse, never the same one twice in a row on this device.
export function pickVerse(): Verse {
  let last = -1;
  try {
    last = Number(localStorage.getItem("lastVerseIndex") ?? -1);
  } catch {}

  let i = Math.floor(Math.random() * verses.length);
  if (verses.length > 1) {
    while (i === last) i = Math.floor(Math.random() * verses.length);
  }

  try {
    localStorage.setItem("lastVerseIndex", String(i));
  } catch {}
  return verses[i];
}